#include <stdio.h>

int main(void) {
    int bowls[5] = {0};
    int n = 0;

    if (scanf("%d", &n) != 1) {
        return 1;
    }

    for (int i = 0; i < n; i++) {
        if (scanf("%d", &bowls[i]) != 1) {
            return 1;
        }
    }

    int big = bowls[0];
    for (int i = 1; i < n; i++) {
        if (bowls[i] > big) {
            big = bowls[i];
        }
    }
    printf("最多的那一只碗里有 %d 条{unit}喵\n", big);
    return 0;
}
